def choose_move(observation):
    # Minimal deterministic move: move toward the center of the grid if possible,
    # otherwise stay or take a step that doesn't collide with an obstacle if provided.
    grid_w = observation.get("grid_width", observation.get("grid_size", 0))
    grid_h = observation.get("grid_height", observation.get("grid_size", 0))
    pos = observation.get("self_position", observation.get("position", (0, 0)))
    obs = observation.get("obstacles", observation.get("blocked", []))
    opp = observation.get("opponent_position", None)

    x, y = pos
    target_x = grid_w // 2
    target_y = grid_h // 2

    # Build a simple preference: move one step toward center, but avoid obstacles if known.
    def is_block(nx, ny):
        if obs:
            for ob in obs:
                if isinstance(ob, dict):
                    ox = ob.get("x", None)
                    oy = ob.get("y", None)
                else:
                    ox, oy = ob[0], ob[1] if hasattr(ob, "__getitem__") else (None, None)
                if ox == nx and oy == ny:
                    return True
        return False

    dx = 0
    dy = 0
    if x < target_x:
        dx = 1
    elif x > target_x:
        dx = -1
    if y < target_y:
        dy = 1
    elif y > target_y:
        dy = -1

    # Try preferred move, then fallback to safe stays or simple adjustments
    moves = [(dx, dy), (dx, 0), (0, dy), (0, 0)]
    for ndx, ndy in moves:
        nx = x + ndx
        ny = y + ndy
        if 0 <= nx < grid_w and 0 <= ny < grid_h:
            if not is_block(nx, ny):
                return [ndx, ndy]

    # If all preferred blocked, stay
    return [0, 0]
